-- Trademark Prosecution in Practice grows from 10 to 15 sessions: five live demonstrations on real Registry
-- examination reports and written submissions. Adds the sessions to the curriculum and updates the course text.
-- Run after 0017.

insert into public.lectures (course_slug, position, title, lessons, published)
  select 'trademark-prosecution-in-practice', 11, 'Live demonstration I: Section 9(1)(a) objection, acquired distinctiveness', '["A real examination report objecting that the mark is devoid of distinctive character, read line by line", "Deciding the route: why inherent distinctiveness will not carry this mark and acquired distinctiveness will", "Building the evidence index on screen: date of first use, invoices across years, advertising spend, sales figures, market presence", "Drafting the user affidavit and the response, paragraph by paragraph, with the annexures numbered as the Registry expects", "Practice exercise 11: respond to a Section 9(1)(a) report with the evidence pack provided"]'::jsonb, false
  where not exists (select 1 from public.lectures where course_slug = 'trademark-prosecution-in-practice' and position = 11);
insert into public.lectures (course_slug, position, title, lessons, published)
  select 'trademark-prosecution-in-practice', 12, 'Live demonstration II: Section 9(1)(b) and 9(1)(c), descriptive, laudatory and customary marks', '["Three real reports: a descriptive word, a laudatory word and a term that has become customary in the trade", "Suggestive or descriptive: the argument that keeps a mark on the inherent-distinctiveness route, and the decisions that support it", "When to disclaim, when to amend the mark, when to limit the specification, and when to concede and refile", "Drafting the three responses live, with the precedents cited the way hearing officers prefer", "Practice exercise 12: classify five marks on the 9(1)(b) spectrum and draft the response for the hardest one"]'::jsonb, false
  where not exists (select 1 from public.lectures where course_slug = 'trademark-prosecution-in-practice' and position = 12);
insert into public.lectures (course_slug, position, title, lessons, published)
  select 'trademark-prosecution-in-practice', 13, 'Live demonstration III: Section 11 citations, distinguishing, consent and rectification', '["A real report citing two earlier marks: comparing marks and goods the way the Registry does, visually, phonetically and conceptually", "Checking the cited marks first: status, renewal, proprietor, evidence of use, and whether a Section 47 rectification is the better reply", "Consents, coexistence and limitation of specification: drafting the letter of consent and the limited specification", "Drafting the Section 11 response live, including the comparison table the Registry reads first", "Practice exercise 13: answer a Section 11 citation two ways, by distinguishing and by limitation, and choose one"]'::jsonb, false
  where not exists (select 1 from public.lectures where course_slug = 'trademark-prosecution-in-practice' and position = 13);
insert into public.lectures (course_slug, position, title, lessons, published)
  select 'trademark-prosecution-in-practice', 14, 'Live demonstration IV: the combined report, formal, Section 9 and Section 11 objections together', '["A real report with every type of objection at once: classification, specification, proprietor details, user claim, Section 9 and Section 11", "Clearing the formal objections in a sentence each, and the TM-M amendments that go with them", "Ordering the response so the Registry reads the strongest point first", "Drafting the complete response live, start to finish, with the full evidence index and annexure list", "Practice exercise 14: respond to a combined report under the one-month deadline"]'::jsonb, false
  where not exists (select 1 from public.lectures where course_slug = 'trademark-prosecution-in-practice' and position = 14);
insert into public.lectures (course_slug, position, title, lessons, published)
  select 'trademark-prosecution-in-practice', 15, 'Live demonstration V: written submissions after the hearing notice, every type of hearing', '["Three real hearing notices: a Section 9 hearing, a Section 11 hearing and a hearing after a deficient response", "What to concede, what to argue and what to annex in a written submission, and the fifteen-day timeline", "Drafting the written submissions live, with the evidence of use, the precedents and the two-minute opening for the hearing day", "After the hearing: review, appeal to the High Court and refiling, and how to advise the client on each", "Practice exercise 15: prepare the written submission package for a Section 11 hearing notice"]'::jsonb, false
  where not exists (select 1 from public.lectures where course_slug = 'trademark-prosecution-in-practice' and position = 15);

update public.courses set
  duration = '30 hours',
  summary  = 'The complete prosecution cycle in fifteen two-hour sessions, all recorded. Half the course is the pre-filing search most juniors are never taught properly; the other half is the examination report, the written submission and the hearing, including five live demonstrations on real Registry examination reports and written submissions covering every type of objection. Fifteen practice exercises, email support throughout, and a community of IP professionals.',
  includes = '["15 recorded sessions, 2 hours each, available for 2 months from registration", "5 live demonstrations on real Registry examination reports and written submissions, covering every type of objection", "15 practice exercises with model answers", "Email support from the instructors throughout the course", "Membership of the VIDIKSHA community of IP professionals", "IP Prosecution Kit delivered to your doorstep", "Certificate on completion of all fifteen exercises"]'::jsonb,
  about    = '["Most trademark training starts at the examination report. This course starts earlier, where the real decisions are made: the search. Six of the fifteen sessions are about finding what is already on the Register and on the market, reading it under Sections 9, 11 and 17, and writing an opinion that tells the client whether to file, change the mark, or walk away.", "The second half is prosecution proper. You read real Registry examination reports, choose the route for each objection, draft the response, and then prepare the written submission and hearing file for the matters that are not waived. Five sessions are pure demonstration: real examination reports and hearing notices of every type, from a Section 9(1)(a) objection to a combined report and a post-hearing written submission, answered live on screen from the first line to the annexure list.", "Every session is recorded, and the recordings stay open to you for two months from the date you register: long enough to work through all fifteen at two sessions a week with time to spare, and to return to the parts you need on a live matter. Fifteen practice exercises, one per session, come with model answers. Questions go by email and are answered by the people who teach the course. Enrolling also places you in the VIDIKSHA community of IP professionals, where practitioners compare notes on real objections and Registry practice.", "You also receive the IP Prosecution Kit at your doorstep: the Vidiksha Trademark Prosecution in Practice book, the prosecution and filing checklists, and the sample drafts the course is built around, printed, so they are on your desk when a real examination report lands."]'::jsonb,
  faq      = '[{"a": "Recorded. All fifteen sessions are available from the day you enrol, so you can watch at your own pace and go back to a session when a live matter needs it. Questions go by email and are answered by the instructors.", "q": "Are the sessions live or recorded?"}, {"a": "Two months from the date of registration. That is comfortably enough for the fifteen sessions and the exercises; if you need longer for a good reason, write to us before the period ends.", "q": "How long do I have access to the recordings?"}, {"a": "The Vidiksha Trademark Prosecution in Practice book, the prosecution checklist, the checklist for filing a trademark, and printed sample drafts for examination report responses, written submissions, and Section 9, Section 11 and common-law clearances. It is couriered to the address you give at registration, within India.", "q": "What is in the IP Prosecution Kit, and how does it reach me?"}, {"a": "A private group of VIDIKSHA members who practise IP: associates, in-house counsel, agents and founders. It is where people compare notes on real objections, hearing experiences and Registry practice, and where we post updates when practice changes.", "q": "What is the community?"}, {"a": "Indian practice under the Trade Marks Act, 1999 and the Trade Marks Rules, 2017, as applied by the Registry today. Sessions are re-recorded when practice changes.", "q": "Which Registry practice does this follow?"}, {"a": "Yes. Search reports, examination reports, responses, written submissions and hearing records from actual matters, with client and mark details altered where needed.", "q": "Are the documents real?"}]'::jsonb,
  outcomes = '["Classify a proposed mark and predict its Section 9 and Section 11 exposure before anyone files", "Build search strings that find phonetic, visual and transliterated variants the plain search misses", "Prepare a complete pre-filing search report with a risk opinion a client can act on", "Run dilution, proprietor and WIPO Global Brand Database searches, and know when transborder reputation matters", "Read a Registry examination report in minutes and choose the right route for each objection", "Draft a response to a Section 9 or Section 11 objection with the evidence index to back it", "Prepare written submissions and a hearing file that survive the hearing officer''s questions", "Keep a prosecution docket clean: deadlines, file hygiene and the records the Registry will ask for", "Answer every type of Registry objection, formal, Section 9 and Section 11, and the hearing notice that follows, from real worked examples"]'::jsonb,
  updated_at = now()
where slug = 'trademark-prosecution-in-practice';
